/* ── The editorial board panels ────────────────────────────── */
/* The board shares the viewport shell with the drawer and main column. It
   consumes real horizontal space without inheriting the masthead offset. */
.editorial-overlay {
  position: relative;
  inset: auto;
  z-index: var(--z-overlay);
  flex: 0 0 auto;
  align-self: stretch;
  width: min(29rem, calc(100% - 3rem));
  height: 100%;
  max-height: none;
  display: flex;
  flex-direction: column;
  gap: 0;
  overflow: hidden;
  border-left: 1px solid var(--color-paper-3);
  background: color-mix(in srgb, var(--color-paper) 94%, transparent);
  box-shadow: -0.35rem 0 0.5rem rgba(32, 25, 16, 0.12);
  backdrop-filter: blur(12px) saturate(0.94);
  pointer-events: auto;
  transform: none;
  transition:
    opacity 180ms cubic-bezier(0.22, 1, 0.36, 1),
    width 180ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 180ms cubic-bezier(0.22, 1, 0.36, 1),
    visibility 180ms ease;
}
.editorial-overlay--apparatus {
  width: min(31rem, calc(100% - 3rem));
}
.editorial-overlay--closed {
  width: 0;
  border-left: 0;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  transform: none;
}
.editorial-overlay__topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 2.75rem;
  padding: 0.5rem 1rem;
  border-bottom: 1px solid var(--color-paper-3);
  color: var(--color-ink);
}
.editorial-overlay__context-line {
  margin-top: 0.1rem;
  font-family: var(--font-typewriter);
  font-size: 0.65rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
}
.editorial-overlay__close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.875rem;
  height: 1.875rem;
  flex: 0 0 auto;
  border: 0;
  border-radius: 2px;
  color: var(--color-ink-muted);
  background: transparent;
  font-family: var(--font-typewriter);
  font-size: 1.1rem;
  line-height: 1;
}
.editorial-overlay__close:hover {
  color: var(--color-ink);
  background: color-mix(in srgb, var(--color-paper-3) 45%, transparent);
}
.editorial-overlay-card {
  overflow: hidden;
  border: 0;
  border-bottom: 1px solid var(--color-paper-3);
  background: transparent;
  box-shadow: none;
  grid-template-columns: repeat(6, minmax(0, 1fr));
}
.editorial-board-context {
  position: relative;
  min-width: 0;
  padding: 0.35rem 0.1rem 0.3rem;
  border-right: 1px solid
    color-mix(in srgb, var(--color-paper-3) 60%, transparent);
  border-bottom: 2px solid transparent;
  color: var(--color-ink-muted);
  text-align: center;
}
.editorial-board-context > span {
  display: block;
  font-family: var(--font-typewriter);
  font-size: 0.5rem;
  line-height: 1.2;
  letter-spacing: 0.1em;
  opacity: 0.8;
}
.editorial-board-context > strong {
  display: block;
  margin-top: 0.05rem;
  font-family: var(--font-display);
  font-size: 0.72rem;
  font-weight: 500;
  white-space: nowrap;
}
.editorial-board-context > small {
  position: absolute;
  top: 0.15rem;
  right: 0.15rem;
  display: inline-flex;
  min-width: 1rem;
  height: 1rem;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: var(--context-accent);
  color: white;
  font-family: var(--font-typewriter);
  font-size: 0.55rem;
}
.editorial-board-context--active {
  border-bottom-color: var(--context-accent);
  color: var(--color-ink);
  background: color-mix(in srgb, var(--context-accent) 7%, transparent);
}
.editorial-board-card__body {
  min-height: 0;
  flex: 1;
  overflow: hidden;
  background: color-mix(in srgb, var(--color-paper-2) 78%, transparent);
}

/* Apparatus monitoring separates the calm Signal Desk from the exact search
