41	/**
42	 * The "Saved Xs ago" line that lives in the editor colophon.
43	 * The Lix mirror (separate from Convex) writes the manuscript
44	 * to the local Lix store on a 1.2s debounce; this label ticks
45	 * to the most recent successful mirror. Until the first mirror
46	 * fires, the line reads "Not saved yet" so the writer always
47	 * knows where the cursor is.
48	 */
49	export const LastSavedLine = component$<{ savedAt: number | null }>(
50	  ({ savedAt }) => {
