10	/**
11	 * The tiny dot in the editor toolbar that shows whether the
12	 * local draft is in sync with the server. The status is
13	 * pushed by `convex-sync` via the `twyne:sync-status` event;
14	 * this component just renders it.
15	 */
16	export const SyncDot = component$(() => {
17	  const status = useSignal<SyncStatus>({ kind: "local-only" });
18	
19	  // eslint-disable-next-line qwik/no-use-visible-task
20	  useVisibleTask$(({ cleanup }) => {
21	    const unsubscribe = subscribeSyncStatus((s) => {
22	      status.value = s;
23	    });
24	    cleanup(() => unsubscribe());
25	  });
26	
27	  return (
28	    <span
29	      class="inline-block w-2 h-2 rounded-full"
30	      style={{
31	        backgroundColor: statusColor(status.value),
32	        boxShadow: "0 0 0 1px rgba(0,0,0,0.04)",
33	        transition: "background-color 200ms ease",
34	      }}
35	      aria-label={statusLabel(status.value)}
36	      title={statusLabel(status.value)}
37	    />
38	  );
39	});
