41	/**
42	 * The "Saved Xs ago" line that lives in the editor colophon.
43	 * The Lix mirror (separate from Convex) writes the manuscript
44	 * to the local Lix store on a 1.2s debounce; this label ticks
45	 * to the most recent successful mirror. Until the first mirror
46	 * fires, the line reads "Not saved yet" so the writer always
47	 * knows where the cursor is.
48	 */
49	export const LastSavedLine = component$<{ savedAt: number | null }>(
50	  ({ savedAt }) => {
51	    // Re-evaluate the label every second so the age stays
52	    // current. The interval is a 1Hz tick — cheap, and the
53	    // label is short enough that the DOM diff is trivial.
54	    const label = useSignal(lastSavedLabel(savedAt));
55	    // eslint-disable-next-line qwik/no-use-visible-task
56	    useVisibleTask$(({ cleanup, track }) => {
57	      track(() => savedAt);
58	      label.value = lastSavedLabel(savedAt);
59	      const tick = setInterval(() => {
60	        label.value = lastSavedLabel(savedAt);
61	      }, 1000);
62	      cleanup(() => clearInterval(tick));
63	    });
64	    return <span>{label.value}</span>;
65	  },
66	);
