49	/**
50	 * A Word-style page ruler with draggable margin markers.
51	 *
52	 * The previous layout tool offered only sliders in a popover, which asks the
53	 * writer to translate "3.25 rem" into a picture of their page. A ruler is
54	 * direct manipulation: the marker sits where the margin is, you drag the edge
55	 * of the text column, and the manuscript reflows underneath. That is what
56	 * "change the margins" means to anyone who has used a word processor.
57	 *
58	 * Dragging is done with pointer capture rather than document-level listeners
59	 * so a drag that leaves the window still ends cleanly, and the keyboard gets
60	 * the same control — arrows nudge by one step, shift by four — because a
61	 * drag-only affordance is unusable without a mouse.
62	 */
63	export const PageRuler = component$<PageRulerProps>((props) => {
64	  const dragging = useSignal<Edge | null>(null);
65	  const readout = useSignal<string>("");
66	
67	  const commit = $((edge: Edge, rem: number) => {
68	    const m = resolveMargins(props.layout);
69	    const opposite = edge === "left" ? m.right : m.left;
70	    const next = clampMargin(edge, rem, opposite, props.pageWidthRem);
71	    void props.onChange$({
72	      ...props.layout,
73	      [edge === "left" ? "marginLeft" : "marginRight"]: next,
74	    });
75	    readout.value = `${next.toFixed(2)} rem`;
76	  });
77	
78	  const onHandleDown = $((edge: Edge, e: PointerEvent, el: HTMLElement) => {
79	    el.setPointerCapture(e.pointerId);
80	    dragging.value = edge;
81	    const track = el.parentElement;
82	    if (!track) return;
83	    const rect = track.getBoundingClientRect();
84	    const px = rootFontSize();
85	    const step = MARGIN_RANGE[edge].step;
86	
87	    const move = (ev: PointerEvent) => {
88	      // Measure from the page edge the marker belongs to, so the number the
89	      // writer sets is the margin itself rather than a position on the ruler.
90	      const fromEdge =
91	        edge === "left" ? ev.clientX - rect.left : rect.right - ev.clientX;
92	      void commit(edge, snap(fromEdge / px, step));
93	    };
94	    const up = () => {
95	      dragging.value = null;
96	      readout.value = "";
97	      el.removeEventListener("pointermove", move);
98	      el.removeEventListener("pointerup", up);
99	      el.removeEventListener("pointercancel", up);
100	    };
101	    el.addEventListener("pointermove", move);
102	    el.addEventListener("pointerup", up);
103	    el.addEventListener("pointercancel", up);
104	  });
105	
106	  /**
107	   * Stop the arrow keys from scrolling the page out from under the writer.
108	   * Must be synchronous — an async QRL runs after the browser has already
109	   * acted on the event — and self-contained, which is what `sync$` enforces.
110	   * Tab is deliberately left alone so the handles stay reachable.
111	   */
112	  const preventScrollKeys = sync$((e: KeyboardEvent) => {
113	    if (["ArrowLeft", "ArrowRight", "Home"].includes(e.key)) {
114	      e.preventDefault();
115	    }
116	  });
117	
118	  const onHandleKey = $((edge: Edge, e: KeyboardEvent) => {
119	    const step = MARGIN_RANGE[edge].step * (e.shiftKey ? 4 : 1);
120	    const m = resolveMargins(props.layout);
121	    const current = edge === "left" ? m.left : m.right;
122	    // Arrows move the marker in screen terms; for the right margin that is
123	    // the opposite of moving the number, since it is measured inward.
124	    if (e.key === "ArrowLeft") {
125	      void commit(edge, current + (edge === "left" ? -step : step));
126	    } else if (e.key === "ArrowRight") {
127	      void commit(edge, current + (edge === "left" ? step : -step));
128	    } else if (e.key === "Home") {
129	      void commit(edge, MARGIN_RANGE[edge].min);
130	    }
131	  });
132	
133	  const m = resolveMargins(props.layout);
134	  const width = props.pageWidthRem;
135	  const leftPct = (m.left / width) * 100;
136	  const rightPct = (m.right / width) * 100;
137	
138	  // A tick every rem, which at the default type size is a comfortable
139	  // approximation of a ruler's inch marks without pretending to be inches.
140	  const ticks = Array.from(
141	    { length: Math.max(0, Math.floor(width)) },
142	    (_, i) => i + 1,
143	  );
144	
145	  return (
146	    <div
147	      class="ruler"
148	      style={{ width: `${width}rem`, maxWidth: "100%" }}
149	      data-dragging={dragging.value ? "true" : "false"}
150	      data-zen={props.zen ? "true" : "false"}
151	      role="group"
152	      aria-label="Page margins"
153	    >
154	      <div class="ruler-track">
155	        <div
156	          class="ruler-column"
157	          style={{ left: `${leftPct}%`, right: `${rightPct}%` }}
158	        />
159	        {ticks.map((t) => (
160	          <span
161	            key={t}
162	            class="ruler-tick"
163	            style={{ left: `${(t / width) * 100}%` }}
164	          />
165	        ))}
166	
167	        <button
168	          type="button"
169	          class="ruler-handle"
170	          style={{ left: `${leftPct}%` }}
171	          title="Left margin — drag, or use the arrow keys"
172	          aria-label="Left margin"
173	          role="slider"
174	          aria-orientation="horizontal"
175	          aria-valuemin={MARGIN_RANGE.left.min}
176	          aria-valuemax={MARGIN_RANGE.left.max}
177	          aria-valuenow={Number(m.left.toFixed(2))}
178	          aria-valuetext={`Left margin ${m.left.toFixed(2)} rem`}
179	          onPointerDown$={(e, el) => onHandleDown("left", e, el)}
180	          onKeyDown$={[
181	            preventScrollKeys,
182	            $((e: KeyboardEvent) => onHandleKey("left", e)),
183	          ]}
184	        />
185	        <button
186	          type="button"
187	          class="ruler-handle"
188	          style={{ left: `${100 - rightPct}%` }}
189	          title="Right margin — drag, or use the arrow keys"
190	          aria-label="Right margin"
191	          role="slider"
192	          aria-orientation="horizontal"
193	          aria-valuemin={MARGIN_RANGE.right.min}
194	          aria-valuemax={MARGIN_RANGE.right.max}
195	          aria-valuenow={Number(m.right.toFixed(2))}
196	          aria-valuetext={`Right margin ${m.right.toFixed(2)} rem`}
197	          onPointerDown$={(e, el) => onHandleDown("right", e, el)}
198	          onKeyDown$={[
199	            preventScrollKeys,
200	            $((e: KeyboardEvent) => onHandleKey("right", e)),
201	          ]}
202	        />
203	
204	        {dragging.value && readout.value && (
205	          <span
206	            class="ruler-readout"
207	            style={{
208	              left:
209	                dragging.value === "left"
210	                  ? `${leftPct}%`
211	                  : `${100 - rightPct}%`,
212	            }}
213	          >
214	            {readout.value}
215	          </span>
216	        )}
217	      </div>
218	    </div>
219	  );
220	});

